/* amirsalmani/status — a state, not a badge.
 *
 * Requires tokens.css. There is no green-amber-red here because there is no
 * accent hue (brand.md §7). State is carried by fill: live is inverted, idle is
 * outlined, retired is faint. A dot marks live only, and it does not pulse.
 */

.as-status {
  display: inline-flex;
  align-items: center;
  gap: .45rem;
  padding: .3rem .6rem;
  border: 1px solid var(--rule);
  border-radius: 999px;
  font-family: var(--mono);
  font-size: .64rem;
  font-weight: 500;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--muted);
  white-space: nowrap;
}
.as-status--live { background: var(--fg); border-color: var(--fg); color: var(--bg); }
.as-status--live::before {
  content: "";
  width: .375rem;
  height: .375rem;
  border-radius: 999px;
  background: currentColor;
}
.as-status--idle { color: var(--fg); border-color: var(--glass-edge); }
.as-status--retired { color: var(--faint); border-style: dashed; }

@media (prefers-contrast: more) { .as-status { border-color: var(--fg); color: var(--fg); } }
